# Generated by tools/sync_install_line_test.py — edit tools/install_line_check.py.template instead.
"""The README's claim about `pip install <this package>` must be what PyPI actually does.

Copied verbatim into each package's `tests/` by `tools/sync_install_line_test.py`. It is one file
because the defect was one class, appearing in six places at once:

* Four packages were published on 2026-07-30 while three files still told readers the install
  would 404.
* `specforge` says "not on PyPI yet", and the name *is* on PyPI — owned by SGLang. `pip install
  specforge` succeeds and installs an unrelated speculative-decoding trainer. A reader following
  that README gets the wrong package with no error.

Both are the same failure: a sentence about a package index, written once, drifting silently. The
only fix that holds is to derive the sentence's truth from the index on every run.

Network-gated. Offline it skips, and a skip is reported as a skip — never counted as a pass.
"""

from __future__ import annotations

import json
import pathlib
import re
import urllib.error
import urllib.request

import pytest
import tomllib

ROOT = pathlib.Path(__file__).resolve().parent.parent
README = (ROOT / "README.md").read_text(encoding="utf-8")
PYPROJECT = tomllib.loads((ROOT / "pyproject.toml").read_text(encoding="utf-8"))["project"]
NAME = PYPROJECT["name"]
DESCRIPTION = PYPROJECT["description"].strip()


def _pypi(package: str):
    try:
        with urllib.request.urlopen(f"https://pypi.org/pypi/{package}/json", timeout=20) as r:
            return json.load(r)["info"]
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        pytest.skip(f"PyPI returned {e.code}")
    except OSError as e:
        pytest.skip(f"no network: {e}")


def _is_ours(info: dict) -> bool:
    """Is the project on the index THIS project?

    A 60-character prefix match in either direction was the first attempt, and a squatter whose
    summary was one word classified as ours. What actually caught the real squat (`specforge`) was
    that SGLang's summary happens to be empty — the check was passing by accident.

    A link home is decisive; failing that, the summaries must agree substantially rather than share
    an opening word. When in doubt this answers "not ours", because a false "ours" is the direction
    that sends a reader to somebody else's package.
    """
    for url in (info.get("project_urls") or {}).values():
        if isinstance(url, str) and "github.com/nickharris808/" in url:
            return True

    summary = (info.get("summary") or "").strip()
    if len(summary) < 30:
        return False
    shorter, longer = sorted((summary, DESCRIPTION), key=len)
    return longer.startswith(shorter[: max(30, len(shorter) - 10)])


# ------------------------------------------------------------------ offline checks


def test_the_readme_makes_exactly_one_claim_about_this_name():
    """Ambiguity here is how the two contradictory sentences coexisted for days."""
    claims = {
        "works": bool(re.search(rf"`pip install {re.escape(NAME)}` works", README)),
        "does not work": bool(re.search(rf"`pip install {re.escape(NAME)}` does not (work|fail)", README)),
        "belongs to somebody else": "belongs to somebody else" in README,
    }
    made = [k for k, v in claims.items() if v]
    assert len(made) == 1, f"README makes {len(made)} claims about `pip install {NAME}`: {made}"


def test_every_git_install_line_points_at_this_repo():
    for url in re.findall(r"git\+(https://[^\"\s)]+)", README):
        assert url.startswith("https://github.com/nickharris808/"), url


def test_the_readme_never_advertises_a_version_that_is_not_released_yet():
    """The README describes the index; `pyproject.toml` describes the next upload.

    They are allowed to differ — that is what a pending release looks like — but only in one
    direction. A README quoting a version nobody can install is the same defect as a README
    quoting an install that 404s, pointed the other way.
    """
    claimed = re.findall(rf"`{re.escape(NAME)}` (\d+\.\d+\.\d+)", README)
    for version in claimed:
        assert _parse(version) <= _parse(PYPROJECT["version"]), (
            f"README advertises {NAME} {version}, which is ahead of pyproject's {PYPROJECT['version']}"
        )


def _parse(version: str) -> tuple[int, ...]:
    return tuple(int(part) for part in version.split("."))


# ------------------------------------------------------------------ against the live index


@pytest.mark.network
def test_the_install_claim_matches_what_pypi_does():
    info = _pypi(NAME)

    if re.search(rf"`pip install {re.escape(NAME)}` works", README):
        assert info is not None, f"README says `pip install {NAME}` works; PyPI has no such project"
        assert _is_ours(info), (
            f"README says `pip install {NAME}` works, but PyPI's {NAME} is not this project:\n"
            f"  PyPI  : {info.get('summary')!r} ({info.get('author') or info.get('home_page')})\n"
            f"  here  : {DESCRIPTION!r}"
        )
        claimed = re.search(rf"`{re.escape(NAME)}` (\d+\.\d+\.\d+)", README)
        if claimed:
            # The README states what a reader can install *today*, so it tracks the index rather
            # than `pyproject.toml`. When a release is staged the two differ, and the offline test
            # above is what holds that difference to one direction.
            assert claimed.group(1) == info["version"], (
                f"README advertises {NAME} {claimed.group(1)}; PyPI serves {info['version']}. "
                "The README describes the index — update it after the upload, not before."
            )
        return

    if "belongs to somebody else" in README:
        assert info is not None, f"README warns {NAME} is squatted, but PyPI has no such project"
        assert not _is_ours(info), (
            f"README warns readers away from `pip install {NAME}`, but PyPI's {NAME} IS this "
            "project now. Remove the warning — it is costing installs."
        )
        return

    assert info is None, (
        f"README says `pip install {NAME}` does not work, but PyPI serves "
        f"{NAME} {info['version']}. Either it was published and the README is stale, or the name "
        f"has been taken by somebody else — check which before changing the text.\n"
        f"  PyPI: {info.get('summary')!r}"
    )


def test_the_package_reports_the_version_its_metadata_declares():
    """`__version__` and `pyproject.toml` are two places for one fact.

    They drifted the moment a release was staged, and nothing noticed: the built wheel said 1.1.1
    while `protocol_bench.__version__` said 1.1.0. A reader debugging against the wrong version
    number is a support cost paid for nothing.
    """
    import importlib

    # The IMPORT name is not always the DISTRIBUTION name, and deriving one from the other held
    # only while every package here had them equal. `specforge` broke it on 2026-08-18: the
    # distribution was renamed `pcar-specforge` (the bare name is SGLang's on PyPI) while the
    # module stayed `specforge`, so this line looked for `pcar_specforge` and the test failed on a
    # package with nothing wrong with it. Ask the installed metadata what top-level modules the
    # distribution actually provides, and only guess when it cannot say.
    module = None
    try:
        import importlib.metadata as _md
        tops = (_md.distribution(NAME).read_text("top_level.txt") or "").split()
        for candidate in tops:
            try:
                module = importlib.import_module(candidate)
                break
            except ImportError:
                continue
    except Exception:
        module = None
    if module is None:
        try:
            module = importlib.import_module(NAME.replace("-", "_"))
        except ImportError:
            pytest.skip(f"{NAME} is not importable in this environment")
    reported = getattr(module, "__version__", None)
    if reported is None:
        pytest.skip(f"{NAME} does not expose __version__")
    assert reported == PYPROJECT["version"], (
        f"{NAME}.__version__ is {reported}; pyproject.toml says {PYPROJECT['version']}"
    )
